    VBuf *u = (VBuf*)user_data; return (sf_count_t)u->data.size(); };
auto seek_cb = +[](sf_count_t offset, int whence, void *user_data) -> sf_count_t {
    VBuf *u = (VBuf*)user_data; sf_count_t base = 0;
    if (whence == SEEK_SET) base = 0; else if (whence == SEEK_CUR) base = u->pos; else if (whence == SEEK_END) base = (sf_count_t)u->data.size(); else return (sf_count_t)-1;
