auto read_cb = +[](void *ptr, sf_count_t count, void *user_data) -> sf_count_t {
    VBuf *u = (VBuf*)user_data; sf_count_t avail = (sf_count_t)u->data.size() - u->pos; if (avail < 0) return 0;
